function validate_pn_profile(pn_profile_s)
% Generated by GitHub Copilot under Lance Lascari's direction.
% Validate the version 1 wrapper; do not change legacy build_pn_struct behavior.

if ~isstruct(pn_profile_s) || ~isscalar(pn_profile_s) || ...
        ~all(isfield(pn_profile_s,{'schema_version','points','representative_index','source'}))
    error('pn_profile:InvalidProfile','Expected a scalar versioned pn_profile_s wrapper.');
end
validateattributes(pn_profile_s.schema_version,{'numeric'},{'real','finite','scalar'});
if pn_profile_s.schema_version~=1
    error('pn_profile:UnsupportedVersion','Only pn_profile_s schema_version 1 is supported.');
end
points=pn_profile_s.points;
if ~isstruct(points) || isempty(points) || ~isrow(points) || ...
        ~all(isfield(points,{'fc','f','n','kvco','comment','name','clock'}))
    error('pn_profile:InvalidPoints','points must be a nonempty row array of legacy pn_struct values.');
end
validateattributes(pn_profile_s.representative_index,{'numeric'}, ...
    {'real','finite','scalar','integer','>=',1,'<=',numel(points)});
if ~ischar(pn_profile_s.source) || isempty(pn_profile_s.source) || ~isrow(pn_profile_s.source)
    error('pn_profile:InvalidSource','source must be a nonempty character row describing the source.');
end
for ii=1:numel(points)
    point=points(ii);
    validateattributes(point.fc,{'numeric'},{'real','finite','scalar','positive'});
    validateattributes(point.kvco,{'numeric'},{'real','finite','scalar'});
    validateattributes(point.f,{'numeric'},{'real','finite','row','positive','nonempty'});
    validateattributes(point.n,{'numeric'},{'real','finite','row','numel',numel(point.f)});
    if numel(point.f)<2 || any(diff(point.f)<=0)
        error('pn_profile:InvalidOffsets','Each curve needs at least two strictly increasing offsets.');
    end
    if ~ischar(point.comment) || ~(isempty(point.comment) || isrow(point.comment)) || ...
            ~ischar(point.name) || isempty(point.name) || ~isrow(point.name)
        error('pn_profile:InvalidText','Point comment and name must be character rows; name cannot be empty.');
    end
    validateattributes(point.clock,{'numeric'},{'real','finite','row','numel',6});
    if ii>1 && point.fc<=points(ii-1).fc
        error('pn_profile:InvalidCarriers','Point carrier frequencies must be strictly increasing and unique.');
    end
end
end
